{
  "packet_id": "H6-T01-1",
  "claim_id": "C005",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C005.component",
    "value": "The reported aggregate does not establish whether the late-start problem is temporary.",
    "scope": "Inference from the 19 late starts among 74 bookings alone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly states that the aggregate does not establish whether the problem is temporary."
    }
  },
  "signal_basis": {
    "component_id": "C005.signal_basis",
    "value": "The aggregate records 19 late starts among 74 bookings without establishing their temporal pattern.",
    "scope": "The reported aggregate alone.",
    "provenance": {
      "refs": [
        {
          "source_id": "P002",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the count and distinguishes aggregate evidence from evidence of persistence, worsening or temporariness."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C005.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported claim."
    }
  },
  "rationale": "The same aggregate can arise from a brief cluster of late starts or delays distributed throughout the period. It therefore cannot establish temporariness. Observing the proposed temporal signal would add evidence beyond the aggregate and does not invalidate this explicitly bounded claim.",
  "uncertainty": "The aggregate leaves the actual temporal character unresolved; the warrant for that limitation is clear.",
  "anomalies": []
}
